// Space Dodger Game
// Canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = canvas.width = canvas.clientWidth || 400;
  const h = canvas.height = canvas.clientHeight || 600;

  // Player ship
  const ship = { x: w / 2, y: h - 40, w: 30, h: 30, speed: 4 };

  // Asteroids array
  const asteroids = [];
  const asteroidSize = 30;
  const spawnInterval = 1000; // ms
  let lastSpawn = 0;
  let score = 0;
  let gameOver = false;

  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  function spawnAsteroid() {
    const x = Math.random() * (w - asteroidSize);
    asteroids.push({ x, y: -asteroidSize, w: asteroidSize, h: asteroidSize, speed: 2 + Math.random() * 2 });
  }

  function update(dt) {
    // ship movement (arrow keys or WASD)
    if (keys.ArrowLeft || keys.a) ship.x -= ship.speed;
    if (keys.ArrowRight || keys.d) ship.x += ship.speed;
    // keep within bounds
    ship.x = Math.max(0, Math.min(w - ship.w, ship.x));

    // asteroids move down (relative to ship moving up)
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // remove off-screen
      if (a.y > h) {
        asteroids.splice(i, 1);
        score++;
      } else if (rectCollide(ship, a)) {
        gameOver = true;
        break;
      }
    }
    // spawn new asteroids
    if (performance.now() - lastSpawn > spawnInterval) {
      spawnAsteroid();
      lastSpawn = performance.now();
    }
  }

  function rectCollide(r1, r2) {
    return !(r2.x > r1.x + r1.w ||
             r2.x + r2.w < r1.x ||
             r2.y > r1.y + r1.h ||
             r2.y + r2.h < r1.y);
  }

  function draw() {
    ctx.clearRect(0, 0, w, h);
    // ship
    ctx.fillStyle = '#0ff';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // asteroids
    ctx.fillStyle = '#f44';
    asteroids.forEach(a => ctx.fillRect(a.x, a.y, a.w, a.h));
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, w, h);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', w / 2 - 60, h / 2);
    }
  }

  let lastTime = 0;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    if (!gameOver) update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
